/* DentalAudit — demo seed data
 * Realistic example audits built relative to today's date, with case-level
 * results generated by a seeded PRNG so the numbers are stable.
 * Everything here is fictional; patient references are pseudonymised.
 */
DA.seed = (function () {
  const U = DA.utils;

  function tpl(key) {
    return DA.templates.find(function (t) { return t.key === key; });
  }

  function iso(daysFromNow) {
    return U.addDays(new Date(), daysFromNow).toISOString();
  }

  /** Copy template criteria with stable, globally unique IDs (auditId_c1, auditId_c2 …). */
  function criteriaFrom(list, auditId) {
    return list.map(function (c, i) {
      return Object.assign({ description: '', parentCriterionId: null }, c, { id: auditId + '_c' + (i + 1) });
    });
  }

  function items(prefix, texts) {
    return texts.map(function (t, i) { return { id: prefix + '_' + (i + 1), text: t }; });
  }

  function crit(name, description, reference, target, numerator, denominator, method) {
    return { name: name, description: description, reference: reference, target: target, measurementMethod: method || 'Clinical record review', numerator: numerator, denominator: denominator };
  }

  /**
   * Generate cases. rates[i] = probability criterion i is met;
   * naRates[i] = probability criterion i is not applicable.
   */
  function makeCases(seed, n, criteria, rates, naRates, fromDays, toDays, refPrefix) {
    const rand = U.rng(seed);
    const clinicians = ['Consultant', 'Specialty registrar', 'DCT', 'DCT', 'Specialty dentist', 'Postgraduate student'];
    const cases = [];
    for (let i = 0; i < n; i++) {
      const day = fromDays + Math.round((toDays - fromDays) * (i / Math.max(1, n - 1))) + Math.round(rand() * 2 - 1);
      const results = {};
      criteria.forEach(function (c, ci) {
        const na = naRates && naRates[ci] ? naRates[ci] : 0;
        const r = rand();
        if (r < na) results[c.id] = 'na';
        else results[c.id] = rand() < rates[ci] ? 'met' : 'not_met';
      });
      cases.push({
        id: 'case_' + seed + '_' + i,
        ref: refPrefix + '-' + String(1000 + Math.floor(rand() * 8999)),
        date: U.isoDay(U.addDays(new Date(), Math.min(0, day))),
        clinician: clinicians[Math.floor(rand() * clinicians.length)],
        results: results,
        notes: '',
        createdAt: iso(Math.min(0, day))
      });
    }
    return cases;
  }

  /** Build a v2 audit from a template (or from scratch when key is null). */
  function audit(id, key, extra) {
    const t = key ? tpl(key) : {};
    const base = {
      id: id,
      title: t.title || '',
      description: t.auditQuestion ? 'Retrospective record-based audit. ' + t.aim : '',
      projectType: t.projectType || 'Clinical Audit',
      specialty: t.specialty || 'Restorative Dentistry',
      department: t.department || 'Restorative Dentistry',
      auditLead: 'Callum Edward',
      collaborators: [{ id: id + '_col1', name: 'Dental nurse lead' }],
      background: t.background || '',
      auditQuestion: t.auditQuestion || '',
      aim: t.aim || '',
      objectives: items(id + '_obj', [
        'Measure current compliance against each criterion',
        'Identify reasons for non-compliance and agree an action plan',
        'Re-audit to confirm improvement'
      ]),
      methodology: 'Retrospective review of consecutive clinical records against pre-defined criteria using a standard data collection form.',
      inclusionCriteria: items(id + '_inc', ['Patients treated in the department during the sample period']),
      exclusionCriteria: items(id + '_exc', ['Records unavailable at the time of data collection']),
      samplingMethod: 'Consecutive sampling',
      collectionMethods: ['Electronic patient records'],
      cycle: 1,
      parentId: null,
      criteria: t.criteria ? criteriaFrom(t.criteria, id) : [],
      cases: [],
      actions: []
    };
    const a = Object.assign(base, extra);
    if (extra && extra.criteria) a.criteria = criteriaFrom(extra.criteria, id);
    return a;
  }

  function build(state) {
    const audits = [];

    // 1. Radiographs — completed last year, re-audit due soon
    const a1 = audit('aud_radiographs', 'radiographs', {
      status: 'completed', targetSampleSize: 40,
      startDate: U.isoDay(U.addDays(new Date(), -400)), targetCompletionDate: U.isoDay(U.addDays(new Date(), -345)),
      completedAt: iso(-345), reauditDate: U.isoDay(U.addDays(new Date(), 20)),
      createdAt: iso(-405), updatedAt: iso(-340)
    });
    a1.cases = makeCases(11, 40, a1.criteria, [0.93, 0.74, 0.83, 0.96], null, -398, -360, 'RAD');
    a1.actions = [
      { id: 'act_r1', text: 'Add mandatory grading field to radiograph template in clinical notes', owner: 'Callum Edward', due: U.isoDay(U.addDays(new Date(), -300)), done: true },
      { id: 'act_r2', text: 'Teaching session on IR(ME)R justification at DCT induction', owner: 'Training lead', due: U.isoDay(U.addDays(new Date(), -280)), done: true },
      { id: 'act_r3', text: 'Laminated grading criteria in each surgery', owner: 'Dental nurse lead', due: U.isoDay(U.addDays(new Date(), -290)), done: false }
    ];
    audits.push(a1);

    // 2. Antimicrobial prescribing — data collection in progress
    const a2 = audit('aud_antimicrobial', 'antimicrobial', {
      status: 'collecting', targetSampleSize: 40,
      startDate: U.isoDay(U.addDays(new Date(), -30)), targetCompletionDate: U.isoDay(U.addDays(new Date(), 12)),
      createdAt: iso(-34), updatedAt: iso(-0.1)
    });
    a2.cases = makeCases(22, 22, a2.criteria, [0.82, 0.9, 0.68, 0.88], null, -29, -1, 'AE');
    audits.push(a2);

    // 3. Medical history — collection complete, analysis stage
    const a3 = audit('aud_medhx', 'medical-history', {
      status: 'analysis', targetSampleSize: 50,
      startDate: U.isoDay(U.addDays(new Date(), -50)), targetCompletionDate: U.isoDay(U.addDays(new Date(), 6)),
      createdAt: iso(-55), updatedAt: iso(-1.2)
    });
    a3.cases = makeCases(33, 50, a3.criteria, [0.95, 0.88, 0.98, 0.8], null, -49, -4, 'RES');
    audits.push(a3);

    // 4. Consent — cycle 1 (completed) and cycle 2 re-audit (completed, improved)
    const a4 = audit('aud_consent_c1', 'consent', {
      status: 'completed', targetSampleSize: 30,
      startDate: U.isoDay(U.addDays(new Date(), -470)), targetCompletionDate: U.isoDay(U.addDays(new Date(), -420)),
      completedAt: iso(-420), reauditDate: U.isoDay(U.addDays(new Date(), -60)),
      createdAt: iso(-475), updatedAt: iso(-418)
    });
    a4.cases = makeCases(44, 30, a4.criteria, [0.97, 0.7, 0.55, 0.8], null, -468, -430, 'OS');
    a4.actions = [
      { id: 'act_c1', text: 'Introduce procedure-specific consent forms listing material risks', owner: 'Oral Surgery consultant', due: U.isoDay(U.addDays(new Date(), -380)), done: true },
      { id: 'act_c2', text: 'Add “alternatives incl. no treatment” prompt to notes template', owner: 'Callum Edward', due: U.isoDay(U.addDays(new Date(), -390)), done: true }
    ];
    audits.push(a4);

    const a4b = audit('aud_consent_c2', 'consent', {
      status: 'completed', cycle: 2, parentId: 'aud_consent_c1', targetSampleSize: 30,
      startDate: U.isoDay(U.addDays(new Date(), -110)), targetCompletionDate: U.isoDay(U.addDays(new Date(), -62)),
      completedAt: iso(-62), reauditDate: U.isoDay(U.addDays(new Date(), 300)),
      createdAt: iso(-112), updatedAt: iso(-60)
    });
    a4b.criteria.forEach(function (c, i) { c.parentCriterionId = a4.criteria[i].id; });
    a4b.cases = makeCases(45, 30, a4b.criteria, [1, 1, 1, 1], null, -108, -70, 'OS');
    a4b.actions = [
      { id: 'act_c3', text: 'Share results at Oral Surgery clinical governance meeting', owner: 'Callum Edward', due: U.isoDay(U.addDays(new Date(), -40)), done: true }
    ];
    audits.push(a4b);

    // 5. BPE — collecting
    const a5 = audit('aud_bpe', 'bpe', {
      status: 'collecting', targetSampleSize: 40,
      startDate: U.isoDay(U.addDays(new Date(), -21)), targetCompletionDate: U.isoDay(U.addDays(new Date(), 30)),
      createdAt: iso(-22), updatedAt: iso(-2)
    });
    a5.cases = makeCases(55, 18, a5.criteria, [0.86, 0.92, 0.7, 0.62], [0, 0, 0.45, 0], -20, -2, 'PER');
    audits.push(a5);

    // 6. Rubber dam — planning
    const a6 = audit('aud_rubberdam', 'rubber-dam', {
      status: 'active', targetSampleSize: 30,
      startDate: U.isoDay(U.addDays(new Date(), 5)), targetCompletionDate: U.isoDay(U.addDays(new Date(), 40)),
      createdAt: iso(-3), updatedAt: iso(-3)
    });
    audits.push(a6);

    // 7. Hypodontia MDT — action planning, overdue
    const HYP = 'Local hypodontia MDT pathway; BOS/RCS guidance on hypodontia';
    const a7 = audit('aud_hypodontia', null, {
      title: 'Hypodontia joint clinic documentation',
      specialty: 'Orthodontics',
      department: 'Orthodontics / Restorative',
      projectType: 'Quality Improvement Project',
      background: 'Joint clinic outcomes must be clearly documented and communicated to patients, families and referring practitioners.',
      auditQuestion: 'Are hypodontia joint clinic assessments and outcomes documented and communicated in a timely way?',
      aim: 'To improve the completeness and timeliness of hypodontia joint clinic documentation.',
      criteria: [
        crit('Missing teeth charted at first joint clinic', 'Congenitally absent teeth are charted at the first MDT visit.', HYP, 100, 'Patients with missing teeth charted', 'New hypodontia patients seen at joint clinic'),
        crit('OPT available and reported', 'A current OPT is available and has a written report.', HYP, 95, 'Patients with a reported OPT', 'New hypodontia patients seen at joint clinic', 'Radiograph review'),
        crit('Outcome letter sent within 4 weeks', 'Clinic outcome letter to GDP and patient sent within 28 days.', HYP, 90, 'Letters sent within 28 days', 'Joint clinic attendances requiring a letter', 'Correspondence review'),
        crit('Treatment options discussion documented', 'Options discussed with the patient/parent are recorded.', HYP, 100, 'Records documenting options discussed', 'New hypodontia patients seen at joint clinic')
      ],
      status: 'action', targetSampleSize: 25,
      startDate: U.isoDay(U.addDays(new Date(), -75)), targetCompletionDate: U.isoDay(U.addDays(new Date(), -3)),
      createdAt: iso(-80), updatedAt: iso(-5)
    });
    a7.cases = makeCases(77, 25, a7.criteria, [0.96, 0.92, 0.6, 0.84], null, -74, -20, 'HYP');
    a7.actions = [
      { id: 'act_h1', text: 'Secretarial tracking of outcome letters with 4-week flag', owner: 'Clinic coordinator', due: U.isoDay(U.addDays(new Date(), 14)), done: false },
      { id: 'act_h2', text: 'Joint clinic proforma with options-discussed checkbox', owner: 'Callum Edward', due: U.isoDay(U.addDays(new Date(), 10)), done: false }
    ];
    audits.push(a7);

    // 8. Smoking cessation for implant patients — completed, re-audit overdue
    const DBOH = 'Delivering Better Oral Health (v4, 2021); local implant assessment pathway';
    const a8 = audit('aud_smoking', null, {
      title: 'Smoking status and cessation advice for implant patients',
      specialty: 'Prosthodontics',
      department: 'Restorative Dentistry (Implants)',
      background: 'Smoking is a major risk factor for implant failure and peri-implantitis; advice and referral should be documented.',
      auditQuestion: 'Do implant assessment records document smoking status, very brief advice and onward referral?',
      aim: 'To ensure smoking status and cessation support are documented for all implant patients.',
      criteria: [
        crit('Smoking status recorded at assessment', 'Current smoking/vaping status recorded at implant assessment.', DBOH, 100, 'Assessments with smoking status recorded', 'All implant assessments in the sample period'),
        crit('Very brief advice (VBA) recorded', 'VBA (ask, advise, act) given to smokers and documented.', DBOH, 90, 'Smokers with VBA documented', 'Implant patients who smoke'),
        crit('Referral to cessation service offered', 'Referral to local stop-smoking service offered and recorded.', DBOH, 80, 'Smokers offered a referral', 'Implant patients who smoke'),
        crit('Implant risk discussed in consent', 'Increased failure risk with smoking discussed during consent.', DBOH, 100, 'Consent records noting smoking risk', 'Implant patients who smoke')
      ],
      status: 'completed', targetSampleSize: 30,
      startDate: U.isoDay(U.addDays(new Date(), -440)), targetCompletionDate: U.isoDay(U.addDays(new Date(), -385)),
      completedAt: iso(-385), reauditDate: U.isoDay(U.addDays(new Date(), -15)),
      createdAt: iso(-445), updatedAt: iso(-380)
    });
    a8.cases = makeCases(88, 30, a8.criteria, [0.97, 0.72, 0.5, 0.9], [0, 0.35, 0.35, 0], -438, -395, 'IMP');
    a8.actions = [
      { id: 'act_s1', text: 'Add VBA prompt to implant assessment template', owner: 'Implant lead', due: U.isoDay(U.addDays(new Date(), -350)), done: true }
    ];
    audits.push(a8);

    // 9. Draft — implant crown torque (partly planned; demonstrates resuming a draft)
    const t9 = tpl('implant-torque');
    const a9 = audit('aud_draft_torque', 'implant-torque', {
      status: 'draft',
      description: 'Record-based audit of implant crown fit appointments.',
      startDate: U.isoDay(U.addDays(new Date(), 14)),
      targetCompletionDate: U.isoDay(U.addDays(new Date(), 120)),
      collectionStartDate: U.isoDay(U.addDays(new Date(), 14)),
      collectionEndDate: U.isoDay(U.addDays(new Date(), 75)),
      targetSampleSize: '',
      samplingMethod: '',
      methodology: '',
      inclusionCriteria: [{ id: 'aud_draft_torque_inc_1', text: 'Screw-retained single implant crowns fitted in the department' }],
      exclusionCriteria: [{ id: 'aud_draft_torque_exc_1', text: '' }],
      createdAt: iso(-1), updatedAt: iso(-0.6)
    });
    a9.criteria = criteriaFrom(t9.criteria.slice(0, 1), 'aud_draft_torque');
    audits.push(a9);

    const activity = [
      { ts: iso(-0.6), type: 'draft', auditId: 'aud_draft_torque', text: 'Saved draft “Documentation of implant crown screw torque”' },
      { ts: iso(-0.1), type: 'case', auditId: 'aud_antimicrobial', text: 'Added case AE-4127 to “Antimicrobial prescribing for acute dental conditions” (22/40)' },
      { ts: iso(-1.2), type: 'updated', auditId: 'aud_medhx', text: 'Moved “Medical history updated at each course of treatment” to Analysis' },
      { ts: iso(-2), type: 'case', auditId: 'aud_bpe', text: 'Added 4 cases to “BPE recording at new patient examination” (18/40)' },
      { ts: iso(-3), type: 'created', auditId: 'aud_rubberdam', text: 'Created audit “Rubber dam use in endodontic treatment”' },
      { ts: iso(-5), type: 'action', auditId: 'aud_hypodontia', text: 'Drafted action plan for “Hypodontia joint clinic documentation”' },
      { ts: iso(-9), type: 'updated', auditId: 'aud_hypodontia', text: 'Moved “Hypodontia joint clinic documentation” to Action planning' },
      { ts: iso(-22), type: 'created', auditId: 'aud_bpe', text: 'Created audit “BPE recording at new patient examination”' },
      { ts: iso(-34), type: 'created', auditId: 'aud_antimicrobial', text: 'Created audit “Antimicrobial prescribing for acute dental conditions”' },
      { ts: iso(-60), type: 'completed', auditId: 'aud_consent_c2', text: 'Completed cycle 2 of “Valid consent documentation for dental extractions”' }
    ].map(function (a, i) { return Object.assign({ id: 'act_seed_' + i }, a); });

    audits.splice(audits.length - 1, 0, torqueAudit(true));

    state.audits = audits.map(DA.model.normaliseAudit);
    state.version = DA.model.SCHEMA_VERSION;
    state.activity = activity;
    state.seeded = true;
    return state;
  }

  /**
   * SYNTHETIC TEST DATA — implant crown torque documentation, Cycle 1 baseline with exact counts:
   * torque documented 30/40 (75%, target 100%); access channel seal recorded 36/40 (90%, target 95%).
   * Used to exercise the quality improvement and re-audit workflow. Not real patient data.
   */
  function torqueAudit(raw) {
    const id = 'aud_torque_test';
    const a = audit(id, 'implant-torque', {
      title: 'Implant Crown Torque Documentation Audit (synthetic test data)',
      description: 'SYNTHETIC TEST DATA — fictional records created to test the quality improvement and re-audit workflow.',
      status: 'action', targetSampleSize: 40,
      samplingMethod: 'Consecutive sampling',
      startDate: U.isoDay(U.addDays(new Date(), -120)), targetCompletionDate: U.isoDay(U.addDays(new Date(), -40)),
      collectionStartDate: U.isoDay(U.addDays(new Date(), -118)), collectionEndDate: U.isoDay(U.addDays(new Date(), -60)),
      reauditMonths: 6,
      createdAt: iso(-122), updatedAt: iso(-45)
    });
    a.criteria = criteriaFrom(tpl('implant-torque').criteria.slice(0, 2), id);
    const met = [30, 36];
    a.cases = [];
    for (let i = 0; i < 40; i++) {
      const day = -118 + Math.round(i * 58 / 39);
      const results = {};
      // Deterministic spread of non-compliant cases through the period.
      a.criteria.forEach(function (c, ci) { results[c.id] = ((i * 7 + ci * 3) % 40) < met[ci] ? 'met' : 'not_met'; });
      a.cases.push({ id: 'case_torque_' + i, ref: 'IMP-' + (2001 + i), date: U.isoDay(U.addDays(new Date(), day)), clinician: ['Consultant', 'Specialty registrar', 'DCT', 'Specialty dentist'][i % 4], results: results, notes: '', createdAt: iso(day) });
    }
    return raw ? a : DA.model.normaliseAudit(a);
  }

  return { build: build, torqueAudit: torqueAudit };
})();
